def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """

    def switch_case(ch):
        if ch.isupper():
            return ch.lower()
        elif ch.islower():
            return ch.upper()
        else:
            return ch

    def vowel_change(ch):
        vowels = "aeiouAEIOU"
        if ch in vowels:
            index = vowels.index(ch)
            return vowels[(index + 2) % len(vowels)]
        else:
            return ch

    return ''.join(switch_case(c) for c in message).join(vowel_change(c) for c in message)

