    The factorial of i is the multiplication of the numbers from 1 to i (1 * 2 * ... * i).
    Example:
    f(5) == [1, 2, 6, 24, 15]
    """

    def factorial(x):
        """Helper function to calculate factorial of x."""
        if x == 0 or x == 1:
            return 1
        result = 1
        for i in range(2, x + 1):
            result *= i
        return result

    def sum_to_n(x):
        """Helper function to calculate the sum of numbers from 1 to x."""
        return x * (x + 1) // 2

    if n == 0:
        return []
    if n == 1:
        return [1]
    if n == 2:
        return [1, 2]

    ans = [1, 2]
    for i in range(3, n + 1):
        if i % 2 == 1:
            ans.append(sum_to_n(i))
        else:
            ans.append(factorial(i))
    return ans
